   500	\begin{definition}[Function field]
   501	\label{def:ha-ch1-function-field}
   502	\source{hartshorne-algebraic-geometry:I.4}
   503	For an irreducible variety $X$, its function field $K(X)$ is the field of rational functions,
   504	equivalently the fraction field of the coordinate ring of any dense affine open subset.
   505	\end{definition}
   506	
   507	\begin{lemma}[Density determines morphisms]
   508	\label{lem:ha-ch1-4-1}
   509	\source{hartshorne-algebraic-geometry:I.4.1}
   510	\dcref{I.4.1}
   511	Two morphisms from $X$ to $Y$ agreeing on a nonempty open subset agree everywhere.
   512	\end{lemma}
   513	\begin{proof}
   514	Embed $Y$ in projective space.  The product map to $\mathbb P^n\times\mathbb P^n$ has image of
   515	the dense open in the diagonal, which is closed (the equations $x_i y_j=x_j y_i$).  Hence its
   516	whole image lies in the diagonal.
   517	\end{proof}
   518	
   519	\begin{lemma}[Principal open as affine]
   520	\label{lem:ha-ch1-4-2}
   521	\source{hartshorne-algebraic-geometry:I.4.2}
   522	\dcref{I.4.2}
   523	If $Y=V(f)\subset\mathbb A^n$, then $\mathbb A^n-Y$ is isomorphic to
   524	$H=V(x_{n+1}f-1)\subset\mathbb A^{n+1}$, and its coordinate ring is $k[x_1,\ldots,x_n]_f$.
   525	\uses{lem:ha-ch1-3-6}
   526	\end{lemma}
   527	\begin{proof}
   528	Projection from $H$ has inverse $(a_1,\ldots,a_n)\mapsto(a_1,\ldots,a_n,1/f(a))$; Lemma 3.6
   529	shows both maps are morphisms.
   530	\end{proof}
   531	
   532	\begin{proposition}[Affine basis]
   533	\label{prop:ha-ch1-4-3}
   534	\source{hartshorne-algebraic-geometry:I.4.3}
   535	\dcref{I.4.3}
   536	Every variety has a basis of open affine subsets.
   537	\uses{lem:ha-ch1-4-2}
   538	\end{proposition}
   539	\begin{proof}
   540	Reduce to quasi-affine $Y\subset\mathbb A^n$.  For $P\in U\subset Y$, choose $f\in I(Ybar-Y)$
   541	with $f(P)\ne0$.  Then $Y-f^{-1}(0)$ is an affine closed subset of the affine principal open
   542	$\mathbb A^n-f^{-1}(0)$ by Lemma 4.2, and lies in $U$ after choosing $f$ from the complement.
   543	\end{proof}
   544	
   545	\begin{theorem}[Rational maps and function fields]
   546	\label{thm:ha-ch1-4-4}
   547	\source{hartshorne-algebraic-geometry:I.4.4}
   548	\dcref{I.4.4}
   549	Dominant rational maps $X\dashrightarrow Y$ correspond bijectively to $k$-embeddings
   550	$K(Y)\hookrightarrow K(X)$, giving an arrow-reversing equivalence with finitely generated field
   551	extensions of $k$.
   552	\uses{prop:ha-ch1-3-5,lem:ha-ch1-4-1}
   553	\end{theorem}
   554	\begin{proof}
   555	Pullback on a dense domain gives the embedding.  Conversely, choose affine generators of $K(Y)$;
   556	after shrinking $X$ they are regular, and Proposition 3.5 gives a morphism to an affine open of
   557	$Y$.  Lemma 4.1 makes the resulting rational map independent of choices.  A finitely generated
   558	field is the function field of the affine variety defined by the relations among a finite set of
   559	field generators, proving essential surjectivity and compatibility with composition.
   560	\end{proof}
   561	
   562	\begin{corollary}[Birational tests]
   563	\label{cor:ha-ch1-4-5}
   564	\source{hartshorne-algebraic-geometry:I.4.5}
   565	\dcref{I.4.5}
   566	For varieties $X,Y$, the following are equivalent: $X,Y$ are birational; they have isomorphic
   567	dense open subsets; and $K(X)\cong K(Y)$ over $k$.
   568	\uses{thm:ha-ch1-4-4}
   569	\end{corollary}
   570	\begin{proof}
   571	Restrict inverse rational maps to common domains for the first implication; an isomorphism of opens
   572	induces an isomorphism of function fields; Theorem 4.4 gives the converse.
   573	\end{proof}
   574	
   575	\begin{theorem}[Primitive element]
   576	\label{thm:ha-ch1-4-6A}
   577	\source{hartshorne-algebraic-geometry:I.4.6A}
   578	\dcref{I.4.6A}
   579	A finite separable extension $L/K$ is generated by one element; over an infinite $K$, a generator
   580	can be chosen as a $K$-linear combination of any finite generating set.
   581	\end{theorem}
   582	\begin{proof}
   583	Hartshorne cites Zariski--Samuel.
   584	\end{proof}
   585	
   586	\begin{theorem}[Separating transcendence bases]
   587	\label{thm:ha-ch1-4-7A}
   588	\source{hartshorne-algebraic-geometry:I.4.7A}
   589	\dcref{I.4.7A}
   590	Every finitely generated separably generated extension has, inside any generating set, a separating
   591	transcendence basis.
   592	\end{theorem}
   593	\begin{proof}
   594	Hartshorne cites Zariski--Samuel.
   595	\end{proof}
   596	
   597	\begin{theorem}[Perfect fields]
   598	\label{thm:ha-ch1-4-8A}
   599	\source{hartshorne-algebraic-geometry:I.4.8A}
   600	\dcref{I.4.8A}
   601	Every finitely generated extension of a perfect field is separably generated.
   602	\end{theorem}
   603	\begin{proof}
   604	Hartshorne cites Zariski--Samuel and Matsumura.
   605	\end{proof}
   606	
   607	\begin{proposition}[Birational hypersurface model]
   608	\label{prop:ha-ch1-4-9}
   609	\source{hartshorne-algebraic-geometry:I.4.9}
   610	\dcref{I.4.9}
   611	Every $r$-dimensional variety is birational to a hypersurface in $\mathbb A^{r+1}$ (and to its
   612	projective closure in $\mathbb P^{r+1}$).
   613	\uses{cor:ha-ch1-4-5}
   614	\end{proposition}
   615	\begin{proof}
   616	Choose a separating transcendence basis $x_1,\ldots,x_r$ and, by the primitive-element theorem,
   617	$y$ with $K(X)=k(x_1,\ldots,x_r,y)$.  Clearing denominators in the algebraic equation of $y$
   618	gives an irreducible equation in $r+1$ variables whose hypersurface has function field $K(X)$.
   619	Apply Corollary 4.5.
   620	\end{proof}

