622	\section{Nonsingular Varieties}
623	
624	\begin{definition}[Local, cotangent, and tangent spaces]
625	\label{def:ha-ch1-tangent-space}
626	\source{hartshorne-algebraic-geometry:I.5}
627	For a point $P$ of an affine variety, let $\mathfrak m_P$ be the maximal ideal of its local ring.
628	The cotangent space is $\mathfrak m_P/\mathfrak m_P^2$ and the Zariski tangent space is its dual.
629	\end{definition}
630	
631	\begin{definition}[Regular local ring and nonsingularity]
632	\label{def:ha-ch1-regular-local}
633	\source{hartshorne-algebraic-geometry:I.5}
634	A noetherian local ring $(A,\mathfrak m,k)$ is regular if
635	$\dim_k\mathfrak m/\mathfrak m^2=\dim A$. A variety is nonsingular at $P$ when its local ring is
636	regular, and singular otherwise.
637	\end{definition}
638	
639	\begin{definition}[Multiplicity]
640	\label{def:ha-ch1-multiplicity}
641	\source{hartshorne-algebraic-geometry:I.5}
642	The multiplicity of a local ring is the normalized leading coefficient of its Hilbert--Samuel
643	polynomial; at a point of a variety it is the multiplicity of its local ring.
644	\end{definition}
645	
646	\begin{theorem}[Jacobian criterion]
647	\label{thm:ha-ch1-5-1}
648	\source{hartshorne-algebraic-geometry:I.5.1}
649	\dcref{I.5.1}
650	For an affine variety $Y\subset\mathbb A^n$, $P$ is nonsingular iff $\mathcal O_{P,Y}$ is
651	regular.  If $\dim Y=r$, this is equivalent to the Jacobian of generators of $I(Y)$ having rank
652	$n-r$ at $P$.
653	\end{theorem}
654	\begin{proof}
655	Translate $P=(a_i)$ to the origin.  The differential map identifies the cotangent space of affine
656	space with $k^n$, and the image of $I(Y)$ has dimension equal to the Jacobian rank.  Thus
657	\(\dim_k\mathfrak m_P/\mathfrak m_P^2+\operatorname{rank}J=n\).  Since
658	\(\dim\mathcal O_{P,Y}=r\), regularity is equivalent to rank $J=n-r$.
659	\end{proof}
660	
661	\begin{proposition}[Embedding-dimension inequality]
662	\label{prop:ha-ch1-5-2A}
663	\source{hartshorne-algebraic-geometry:I.5.2A}
664	\dcref{I.5.2A}
665	For a noetherian local ring $(A,\mathfrak m,k)$, \(\dim_k\mathfrak m/\mathfrak m^2\ge\dim A\), with equality precisely when $A$ is regular.
666	\end{proposition}
667	\begin{proof}
668	Hartshorne cites Atiyah--Macdonald and Matsumura.
669	\end{proof}
670	
671	\begin{theorem}[Openness of the nonsingular locus]
672	\label{thm:ha-ch1-5-3}
673	\source{hartshorne-algebraic-geometry:I.5.3}
674	\dcref{I.5.3}
675	For every variety $Y$, $\operatorname{Sing}Y$ is a proper closed subset.
676	\end{theorem}
677	\begin{proof}
678	On an affine chart of dimension $r$ it is cut out by $I(Y)$ and all $(n-r)\times(n-r)$ Jacobian
679	minors, hence is closed.  Birationality reduces properness to an irreducible hypersurface
680	$f=0$.  If every point were singular, all partial derivatives would vanish on $Y$, hence would
681	be multiples of $f$; their lower degrees force them to be zero.  In characteristic zero this is
682	impossible.  In characteristic $p$, $f$ is a polynomial in the $p$th powers of the variables,
683	and algebraic closedness makes $f$ a $p$th power, contradicting irreducibility.
684	\end{proof}
685	
686	\begin{theorem}[Completion of local rings]
687	\label{thm:ha-ch1-5-4A}
688	\source{hartshorne-algebraic-geometry:I.5.4A}
689	\dcref{I.5.4A}
690	For a noetherian local ring $A$ with completion $\widehat A$: $\widehat A$ is local with maximal
691	ideal $\mathfrak m\widehat A$ and $A\hookrightarrow\widehat A$; the completion of every finite
692	$A$-module $M$ is $M\otimes_A\widehat A$; \(\dim\widehat A=\dim A\); and $A$ is regular iff
693	$\widehat A$ is regular.
694	\end{theorem}
695	\begin{proof}
696	Hartshorne cites Atiyah--Macdonald and Zariski--Samuel.
697	\end{proof}
