699	\begin{theorem}[Cohen structure theorem]
700	\label{thm:ha-ch1-5-5A}
701	\source{hartshorne-algebraic-geometry:I.5.5A}
702	\dcref{I.5.5A}
703	If a complete regular local ring of dimension $n$ contains a field, then it is isomorphic to
704	$k[[x_1,\ldots,x_n]]$ over its residue field $k$.
705	\end{theorem}
706	\begin{proof}
707	Hartshorne cites Matsumura and Zariski--Samuel.
708	\end{proof}
